import { GameId, Seat, UserId, WinReason } from "./types.ts";
import { Move } from "./Move.ts";

/**
 * Domain Events
 *
 * Events generated by the Game aggregate when state changes occur.
 * These drive the application layer's side effects (persistence, notifications, etc.)
 */

export type GameEventType =
  | "GameStarted"
  | "GameFinished"
  | "GameReady"
  | "MovePlayed"
  | "PlayerJoined"
  | "PlayerLeft"
  | "PlayerBlocked"
  | "PlayerReadyChanged"
  | "TurnAdvanced";

export interface GameStartedPayload {
  gameId: GameId;
  firstSeat: Seat;
}

export interface GameFinishedPayload {
  gameId?: GameId;
  winnerUserId: UserId;
  reason: WinReason;
  trappedSeat?: Seat | null;
}

export interface MovePlayedPayload {
  gameId?: GameId;
  seat: Seat;
  move: Move;
  turnNumber: number;
}

export interface PlayerJoinedPayload {
  gameId: GameId;
  seat: Seat;
}

export interface TurnAdvancedPayload {
  gameId: GameId;
  newCurrentSeat: Seat;
  phase: string;
}

export interface PlayerLeftPayload {
  gameId: GameId;
  userId: UserId;
}

export interface PlayerReadyChangedPayload {
  gameId: GameId;
  seat: Seat;
  ready: boolean;
  readyStatuses: { seat: Seat; ready: boolean }[];
}

export interface GameReadyPayload {
  gameId: GameId;
}

export type GameEventPayload =
  | GameStartedPayload
  | GameFinishedPayload
  | MovePlayedPayload
  | PlayerJoinedPayload
  | TurnAdvancedPayload
  | PlayerLeftPayload
  | PlayerReadyChangedPayload
  | GameReadyPayload;

export class GameEvent {
  constructor(
    public readonly type: GameEventType,
    public readonly payload: GameEventPayload,
    public readonly aggregateId?: number,
  ) {}
}
